  "accLinkFailed": "Dieser Link ist möglicherweise abgelaufen oder wurde bereits verwendet. Öffne „Konto“, um dich anzumelden oder eine neue E-Mail anzufordern.",
  "privFooter": "Datenschutz & Speicher",
  "privTitle": "Datenschutz und Browserspeicher",
  "privClose": "Datenschutzhinweis schließen",
  "privWho": "Wer ist verantwortlich?",
  "privWhat": "Was wir verwenden und warum",
  "privStorage": "Browserspeicher",
  "privOther": "Weitere bestehende Funktionen",
  "privProviders": "Dienstleister und internationale Übermittlungen",
  "privRetention": "Aufbewahrung und Löschung",
  "privRights": "Deine Rechte",
  "noticeReopen": "Speicherhinweis",
  "noticeLabel": "Hinweis zum Browserspeicher",
  "noticeText": "Cook nutzt Browserspeicher für die von dir genutzten Koch- und Anmeldefunktionen. Es wird kein Speicher für Werbung oder Analyse verwendet.",
  "noticeClose": "Speicherhinweis schließen",
  "privDraftLabel": "Entwurf – aktualisiert am 28. Oktober 2026.",
  "privDraft": "Die Kontofunktionen werden derzeit getestet. Die folgenden Angaben zum Betreiber und zu den Diensten müssen vor dem öffentlichen Start ergänzt werden.",
  "privWho1": "Cook wird betrieben von [vollständiger Name und Postanschrift des Betreibers]. Bei Fragen und Anliegen zum Datenschutz wende dich an [E-Mail-Adresse für Datenschutz]. Diese Angaben müssen ergänzt werden, bevor die Registrierung geöffnet wird.",
  "privWhat1": "Wenn du ein Konto erstellst, verwenden wir deine E-Mail-Adresse, eine Kontokennung, Daten zur Passwort-Authentifizierung und den Bestätigungsstatus, um dein Konto bereitzustellen und zu schützen. Passwörter werden vom Authentifizierungsanbieter als sichere Hashes verarbeitet; Cook speichert keine lesbaren Passwörter. Wir speichern deinen Küchenaufbau, die gewählte Sprache, das Design und die Maßeinheiten, um deine Einstellungen auf allen Geräten wiederherzustellen. Für ein Konto sind E-Mail-Adresse und Passwort erforderlich; Rezepte kannst du auch ohne Konto ansehen.",
  "privWhat2": "Die Verarbeitung von Konto- und Einstellungsdaten ist erforderlich, um den von dir gewünschten Kontodienst bereitzustellen (Art. 6 Abs. 1 lit. b DSGVO). Begrenzte Sicherheits- und Missbrauchsschutzdaten können auf Grundlage berechtigter Interessen (Art. 6 Abs. 1 lit. f DSGVO) verarbeitet werden, soweit dies erforderlich und nach Abwägung zulässig ist. Bestätigungs- und Passwort-Zurücksetzungs-E-Mails sind Servicenachrichten, keine Werbung. Durch die Kontofunktion wird keine Werbung und keine Analyse hinzugefügt.",
  "privStorage1": "Cook nutzt sessionStorage, um deine Küche, deinen Kochfortschritt und deine Auswahl zwischen Seiten im selben Tab mitzunehmen. Wenn du angemeldet bist, enthält er auch deine Anmeldesitzung. Der Browser löscht diese Daten normalerweise, wenn die Tab-Sitzung endet; die Sitzungswiederherstellung des Browsers kann sie jedoch erhalten. Beim Abmelden werden die Tab-Daten von Cook gelöscht. Das Ausblenden des Speicherhinweises wird nur in diesem Tab gespeichert. Die eigenen Skripte von Cook setzen keine Cookies. Deine Hosting- oder Dienstanbieter können eine eigene Sicherheitsverarbeitung haben, die vor dem Start dokumentiert werden muss.",
  "privStorage2": "OK und die Schließen-Schaltfläche des Speicherhinweises blenden den Hinweis nur aus. Sie erlauben keine Analyse, Werbung oder sonstiges optionales Tracking. Jeder künftige nicht notwendige Speicher erfordert vor Beginn eine gesonderte Wahl, mit ebenso einfacher Ablehnung und Widerruf.",
  "privOther1": "Die aktuelle Sprachfunktion der Rezeptliste fragt bei country.is anhand deiner IP-Adresse ein ungefähres Land ab, um eine Sprache für die Spracherkennung zu wählen. Wenn du die Mikrofonerkennung nutzt, kann dein Browser Audio an seinen Spracherkennungsdienst senden. Stattdessen kannst du Zutaten auch eintippen. Diese Anbieter, ihre Richtlinien und die Rechtsgrundlage dieser Funktionen müssen vor dem öffentlichen Start geprüft werden.",
  "privProviders1": "Geplanter Kontoanbieter: Supabase (verwaltetes PostgreSQL und Authentifizierung) mit einer ausgewählten Datenbankregion in der EU. E-Mail-Anbieter: [Anbieter]. Webhosting: [Anbieter]. Der Betreiber muss die tatsächlichen Anbieter, Auftragsverarbeitungsverträge, Unterauftragsverarbeiter, Speicherorte von Protokollen und etwaige Übermittlungen außerhalb des EWR bestätigen. Eine EU-Datenbankregion schließt internationale Übermittlungen nicht automatisch aus. Gegebenenfalls sind der zutreffende Angemessenheitsbeschluss oder die vertraglichen Garantien anzugeben und wie man eine Kopie erhält.",
  "privRetention1": "Kontoeinstellungen werden gespeichert, solange dein Konto aktiv ist. Du kannst die Löschung über den oben genannten Datenschutzkontakt beantragen. Vor dem Start muss der Betreiber das Verfahren zur Bearbeitung von Löschanfragen, die Frist für unbestätigte Konten sowie die Aufbewahrungsfristen für Sicherheitsprotokolle und Backups festlegen. Gelöschte Daten können bis zum Ende der dokumentierten Aufbewahrungsfrist in zugriffsbeschränkten Backups verbleiben.",
  "privRights1": "Je nach den geltenden Voraussetzungen kannst du Auskunft, Berichtigung, Löschung, Einschränkung und Datenübertragbarkeit verlangen oder einer Verarbeitung auf Grundlage berechtigter Interessen widersprechen. Wende dich an den oben genannten Betreiber; Anfragen werden in der Regel innerhalb eines Monats beantwortet, eine rechtlich zulässige Verlängerung wird begründet. Du kannst dich bei deiner Aufsichtsbehörde beschweren, darunter die ungarische NAIH unter naih.hu. Cook verwendet Kontoeinstellungen nicht für automatisierte Entscheidungen mit rechtlicher oder ähnlich erheblicher Wirkung.",
  "favOnly": "Nur Favoriten",
